mapper.select:
select
sd.D_Name as stDName,
mn.*
from OA_Supervision_Task mn
left join OA_Supervision_Task_Department std on mn.St_Id=std.St_Id
left join SYS_Department sd on std.Std_Did=sd.D_Id
where
mn.St_State!=3 and


    and mn.Te_Id = #{params.teId}


    and mn.St_D_Id = #{params.stDId}


    and mn.St_Type = #{params.stType}


    and mn.St_Handle_Type = #{params.stHandleType}

select
sd.D_Name as stDName,

mn.*
from OA_Supervision_Task mn

left join SYS_Department sd on mn.St_D_Id=sd.D_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.St_D_Id = #{params.stDId}


    and mn.St_Code like concat('%',#{params.stCode},'%')


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.St_Create_Time desc
    

limit #{params.start},#{params.size}

select
count(1)
from OA_Supervision_Task mn
left join Pre_Project pro on pro.P_Id=mn.P_Id
where 1=1

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.St_D_Id = #{params.stDId}


    and mn.St_Code like concat('%',#{params.stCode},'%')


    and pro.P_Name like concat('%',#{params.pName},'%')
